package edu.fuzzy;
import jakarta.servlet.http.*;
import java.util.*;
import java.security.Principal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.security.authentication.*;
import org.springframework.security.core.*;
import org.springframework.security.core.context.*;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.web.context.SecurityContextRepository;
import org.springframework.http.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.mail.SimpleMailMessage;
import static edu.fuzzy.Db.*;
@Controller
public class WebController {
 @Value("${fuzzy.hosted:false}") private boolean hosted;
 private final Db db;private final AccountService accounts;private final WorkflowService flow;private final IdentityService identity;private final OtpService otp;private final AuthenticationManager manager;private final UserDetailsService users;private final SecurityContextRepository contexts;private final boolean demo,smtp;private final ObjectProvider<JavaMailSender> mail;private final String profile;
 public WebController(Db db,AccountService accounts,WorkflowService flow,IdentityService identity,OtpService otp,AuthenticationManager manager,UserDetailsService users,SecurityContextRepository contexts,@Value("${fuzzy.demo}")boolean demo,@Value("${fuzzy.smtp}")boolean smtp,ObjectProvider<JavaMailSender> mail,org.springframework.core.env.Environment env){this.db=db;this.accounts=accounts;this.flow=flow;this.identity=identity;this.otp=otp;this.manager=manager;this.users=users;this.contexts=contexts;this.demo=demo;this.smtp=smtp;this.mail=mail;this.profile=String.join(",",env.getActiveProfiles().length==0?env.getDefaultProfiles():env.getActiveProfiles());}
 @ModelAttribute public void common(Model model,Principal p,HttpSession session){model.addAttribute("demo",demo);model.addAttribute("showLocalCredentials",demo&&!hosted);model.addAttribute("database",profile.contains("mysql")?"MySQL · fuzzy_demo":"H2 · persistent demo");if(p!=null){var u=db.user(p.getName());model.addAttribute("me",u);model.addAttribute("keyLabel",AccountService.masked(str(u,"key_id")));model.addAttribute("fuzzyValid",validFuzzy(session,u));}}
 private Map<String,Object> me(Principal p){if(p==null)throw new org.springframework.security.access.AccessDeniedException("Sign in first.");return db.user(p.getName());}
 private boolean validFuzzy(HttpSession s,Map<String,Object>u){return str(u,"id").equals(s.getAttribute("fuzzyUser"))&&s.getAttribute("fuzzyUntil") instanceof Long t&&now()<t;}
 private void fuzzy(HttpSession s,Map<String,Object>u){AccountService.approved(u);if(!validFuzzy(s,u))throw new org.springframework.security.access.AccessDeniedException("Complete a successful fuzzy identity check first. It is valid for 10 minutes.");}
 private String success(RedirectAttributes a,String message,String route){a.addFlashAttribute("success",message);return "redirect:"+route;}
 @GetMapping("/")public String home(){return "redirect:/dashboard";}
 @GetMapping("/login")public String login(){return "login";}
 @PostMapping("/login")public String loginPost(@RequestParam String email,@RequestParam String password,HttpServletRequest request,HttpServletResponse response,RedirectAttributes a){
  HttpSession s=request.getSession();s.removeAttribute("otp");s.removeAttribute("fuzzyUser");s.removeAttribute("fuzzyUntil");SecurityContext empty=SecurityContextHolder.createEmptyContext();SecurityContextHolder.setContext(empty);contexts.saveContext(empty,request,response);
  try{manager.authenticate(UsernamePasswordAuthenticationToken.unauthenticated(email.trim().toLowerCase(),password));var state=otp.issue(email.trim().toLowerCase(),now());
   if(!demo&&!smtp)throw new IllegalArgumentException("OTP delivery is not configured. Enable SMTP or the explicitly labelled demo mode.");
   if(smtp){JavaMailSender sender=mail.getIfAvailable();if(sender==null)throw new IllegalArgumentException("SMTP delivery is unavailable.");SimpleMailMessage message=new SimpleMailMessage();message.setTo(state.email);message.setSubject("Fuzzy Integrity Auditing — one-use sign-in code");message.setText("Your sign-in code is "+state.code+". Expires in three minutes.");sender.send(message);}
   s.setAttribute("otp",state);return "redirect:/otp";
  }catch(org.springframework.security.core.AuthenticationException e){return success(a,"Invalid email or password.","/login");}
 }
 @GetMapping("/otp")public String otpPage(HttpSession s,Model m){var state=(OtpService.State)s.getAttribute("otp");if(state==null)return "redirect:/login";m.addAttribute("otpEmail",state.email);m.addAttribute("expires",new Date(state.expires));return "otp";}
 @GetMapping("/demo-inbox")public String demoInbox(HttpSession s,Model m){if(!demo)throw new org.springframework.security.access.AccessDeniedException("Simulated inbox is disabled.");var state=(OtpService.State)s.getAttribute("otp");if(state==null||state.used||now()>state.expires)throw new IllegalArgumentException("No active OTP in this browser session. Sign in again.");m.addAttribute("otpEmail",state.email);m.addAttribute("otpCode",state.code);m.addAttribute("expires",new Date(state.expires));return "demo-inbox";}
 @PostMapping("/otp")public String verifyOtp(@RequestParam String code,HttpServletRequest request,HttpServletResponse response){HttpSession s=request.getSession();var state=(OtpService.State)s.getAttribute("otp");otp.verify(state,code,now());var details=users.loadUserByUsername(state.email);Authentication auth=UsernamePasswordAuthenticationToken.authenticated(details,null,details.getAuthorities());request.changeSessionId();SecurityContext context=SecurityContextHolder.createEmptyContext();context.setAuthentication(auth);SecurityContextHolder.setContext(context);contexts.saveContext(context,request,response);s.removeAttribute("otp");return "redirect:/dashboard";}
 @GetMapping("/register")public String register(){return "register";}
 @PostMapping("/register")public String registerPost(@RequestParam Map<String,String>form,@RequestParam(required=false)MultipartFile signature,RedirectAttributes a)throws Exception{accounts.register(form,signature);return success(a,"Registration saved. Sign in to see your pending KGC approval.","/login");}
 @GetMapping("/dashboard")public String dashboard(Principal p,Model m){var u=me(p);String role=str(u,"role"),id=str(u,"id");m.addAttribute("role",role);if(role.equals("KGC")){m.addAttribute("users",db.jdbc.queryForList("select id,email,display_name,approval,key_id,issued_at,created_at from app_user where role='USER' order by created_at desc"));}else if(role.equals("USER")){m.addAttribute("fileCount",db.jdbc.queryForObject("select count(*) from stored_file where owner_id=?",Integer.class,id));m.addAttribute("auditCount",db.jdbc.queryForObject("select count(*) from audit_record where requester_id=?",Integer.class,id));m.addAttribute("requestCount",db.jdbc.queryForObject("select count(*) from share_request r join stored_file f on f.id=r.file_id where f.owner_id=? and r.request_state='PENDING'",Integer.class,id));}else{m.addAttribute("queue",db.jdbc.queryForList("select a.id,a.audit_state,a.audit_mode,a.created_at,f.display_name,u.display_name requester from audit_record a join stored_file f on f.id=a.file_id join app_user u on u.id=a.requester_id order by a.created_at desc"));}return "dashboard";}
 @GetMapping("/kgc/users/{id}")public String inspect(@PathVariable String id,Model m){var u=db.one("select * from app_user where id=? and role='USER'",id);m.addAttribute("account",u);m.addAttribute("accountKey",AccountService.masked(str(u,"key_id")));return "inspect";}
 @GetMapping("/kgc/users/{id}/signature")public ResponseEntity<byte[]> signature(@PathVariable String id){var u=db.one("select signature_data from app_user where id=?",id);byte[]image=(byte[])u.get("signature_data");if(image==null)return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.IMAGE_PNG).cacheControl(CacheControl.noStore()).body(image);}
 @PostMapping("/kgc/users/{id}/decide")public String decideUser(Principal p,@PathVariable String id,@RequestParam String decision,RedirectAttributes a)throws Exception{if(!Set.of("APPROVED","REJECTED").contains(decision))throw new IllegalArgumentException("Invalid decision");accounts.decide(me(p),id,decision.equals("APPROVED"));return success(a,"Registration "+decision+". Recipient notification recorded.","/dashboard");}
 @GetMapping("/user/fuzzy")public String fuzzyPage(Principal p){AccountService.approved(me(p));return "fuzzy";}
 @PostMapping("/user/fuzzy")public String fuzzyPost(Principal p,HttpSession s,@RequestParam String attributes,Model m){var u=me(p);AccountService.approved(u);s.removeAttribute("fuzzyUser");s.removeAttribute("fuzzyUntil");var result=identity.match(str(u,"attributes"),attributes);if(result.accepted()){s.setAttribute("fuzzyUser",str(u,"id"));s.setAttribute("fuzzyUntil",now()+600000);}m.addAttribute("sample",attributes);m.addAttribute("match",result);m.addAttribute("fuzzyValid",result.accepted());return "fuzzy";}
 @GetMapping("/user/files")public String files(Principal p,Model m){var u=me(p);AccountService.approved(u);m.addAttribute("files",db.jdbc.queryForList("select * from stored_file where owner_id=? order by created_at desc",str(u,"id")));m.addAttribute("catalogue",db.jdbc.queryForList("select f.id,f.display_name,f.file_version,f.original_length,u.display_name owner_name from stored_file f join app_user u on u.id=f.owner_id where f.owner_id<>? order by f.created_at desc",str(u,"id")));return "files";}
 @PostMapping("/user/upload")public String upload(Principal p,HttpSession s,@RequestParam MultipartFile file,@RequestParam(defaultValue="")String previous,RedirectAttributes a)throws Exception{var u=me(p);fuzzy(s,u);String id=flow.upload(u,file,previous);return success(a,"File encrypted and stored. Trusted baseline recorded.","/files/"+id);}
 @GetMapping("/files/{id}")public String file(Principal p,@PathVariable String id,Model m)throws Exception{var u=me(p);var f=flow.file(id);if(str(u,"role").equals("USER")){AccountService.approved(u);if(!flow.canDownload(u,f)&&!str(f,"owner_id").equals(str(u,"id"))){m.addAttribute("accessDenied",true);}m.addAttribute("isOwner",str(f,"owner_id").equals(str(u,"id")));}m.addAttribute("file",f);m.addAttribute("blocks",(num(f,"envelope_length")+65535)/65536);return "file";}
 @GetMapping("/user/files/{id}/download")public ResponseEntity<byte[]> download(Principal p,HttpSession s,@PathVariable String id)throws Exception{var u=me(p);fuzzy(s,u);byte[]plain=flow.download(u,id);String name=str(flow.file(id),"display_name");return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).cacheControl(CacheControl.noStore()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(name,java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(plain);}
 @PostMapping("/user/files/{id}/request-access")public String requestAccess(Principal p,@PathVariable String id,RedirectAttributes a){flow.requestAccess(me(p),id);return success(a,"Access request sent to the owner.","/user/shares");}
 @GetMapping("/user/shares")public String shares(Principal p,Model m){var u=me(p);AccountService.approved(u);m.addAttribute("incoming",db.jdbc.queryForList("select r.*,f.display_name,u.display_name requester from share_request r join stored_file f on f.id=r.file_id join app_user u on u.id=r.requester_id where f.owner_id=? order by r.created_at desc",str(u,"id")));m.addAttribute("outgoing",db.jdbc.queryForList("select r.*,f.display_name from share_request r join stored_file f on f.id=r.file_id where r.requester_id=? order by r.created_at desc",str(u,"id")));return "shares";}
 @PostMapping("/user/shares/{id}/decide")public String shareDecision(Principal p,@PathVariable String id,@RequestParam String decision,RedirectAttributes a){flow.decideShare(me(p),id,decision);return success(a,"Access decision saved; recipient notified.","/user/shares");}
 @PostMapping("/user/files/{id}/audit")public String requestAudit(Principal p,HttpSession s,@PathVariable String id,@RequestParam String mode,RedirectAttributes a){var u=me(p);fuzzy(s,u);String audit=flow.requestAudit(u,id,mode);return success(a,"Audit requested. TPA must create and forward the challenge.","/audits/"+audit);}
 @GetMapping("/audits")public String audits(Principal p,Model m){var u=me(p);String sql="select a.id,a.audit_state,a.audit_mode,a.created_at,f.display_name,u.display_name requester from audit_record a join stored_file f on f.id=a.file_id join app_user u on u.id=a.requester_id";if(str(u,"role").equals("USER")){AccountService.approved(u);m.addAttribute("queue",db.jdbc.queryForList(sql+" where a.requester_id=? order by a.created_at desc",str(u,"id")));}else m.addAttribute("queue",db.jdbc.queryForList(sql+" order by a.created_at desc"));return "audits";}
 @GetMapping("/audits/{id}")public String audit(Principal p,@PathVariable String id,Model m)throws Exception{var u=me(p);var a=flow.audit(u,id);m.addAttribute("audit",a);m.addAttribute("challenge",flow.decode(str(a,"challenge_json"),AuditProtocol.Challenge.class));if(!str(u,"role").equals("CLOUD"))m.addAttribute("result",flow.decode(str(a,"result_json"),AuditProtocol.Result.class));m.addAttribute("blocks",(num(flow.file(str(a,"file_id")),"envelope_length")+65535)/65536);return "audit";}
 @PostMapping("/tpa/audits/{id}/challenge")public String challenge(Principal p,@PathVariable String id,RedirectAttributes a)throws Exception{flow.challenge(me(p),id);return success(a,"Challenge created and forwarded to the cloud queue.","/audits/"+id);}
 @PostMapping("/cloud/audits/{id}/respond")public String respond(Principal p,@PathVariable String id,RedirectAttributes a)throws Exception{flow.respond(me(p),id);return success(a,"Cloud response operation recorded. Inspect the current audit state.","/audits/"+id);}
 @PostMapping("/tpa/audits/{id}/verify")public String verify(Principal p,@PathVariable String id,RedirectAttributes a)throws Exception{flow.verify(me(p),id);return success(a,"Backend verification completed; terminal result persisted.","/audits/"+id);}
 @GetMapping("/cloud/files")public String cloudFiles(Model m){m.addAttribute("files",db.jdbc.queryForList("select f.id,f.display_name,f.file_version,f.envelope_length,f.created_at,u.display_name owner_name from stored_file f join app_user u on u.id=f.owner_id order by f.created_at desc"));m.addAttribute("events",db.jdbc.queryForList("select * from tamper_event order by created_at desc"));return "cloud-files";}
 @PostMapping("/cloud/files/{id}/tamper")public String tamper(Principal p,@PathVariable String id,@RequestParam int block,RedirectAttributes a)throws Exception{flow.tamper(me(p),id,block);return success(a,"A real ciphertext byte was flipped in block "+block+". Trusted baseline was not changed.","/cloud/files");}
 @GetMapping("/notifications")public String notifications(Principal p,Model m){m.addAttribute("messages",db.jdbc.queryForList("select message,created_at from notification where recipient_id=? order by created_at desc",str(me(p),"id")));return "notifications";}
 @GetMapping("/performance")public String performance(Principal p,Model m){String role=str(me(p),"role");if(!Set.of("CLOUD","TPA").contains(role))throw new org.springframework.security.access.AccessDeniedException("Performance analysis is available to cloud and TPA roles.");m.addAttribute("uploads",db.jdbc.queryForList("select display_name,original_length,upload_ms from stored_file order by created_at desc"));m.addAttribute("timings",db.jdbc.queryForList("select id,audit_state,challenge_ms,response_ms,verify_ms from audit_record order by created_at desc"));return "performance";}
 @GetMapping("/about")public String about(){return "about";}
 @GetMapping("/health")@ResponseBody public Map<String,String>health(){db.jdbc.queryForObject("select 1",Integer.class);return Map.of("status","UP","database",profile.contains("mysql")?"MySQL":"H2","storage","Local cloud simulator");}
}
